import React from "react";
import { Link } from "react-router-dom";

const Header = () => {
    return (
        <div className="header">
            <header>
             
                <p >    <a style={{fontSize:"large"}}>Inventory</a> <a><Link to="/home">HOME</Link></a>
                <a><Link to="/products">PRODUCTS</Link></a>
                <a><Link to="/category">CATEGORIES</Link></a>
                <a><Link to="/brand">BRANDS</Link></a></p>
            
            </header>
        </div>
    );};
export default Header;
